(* [comment removed for export] *)
Definition fh_side (m : mem) (P E lo shi : Z) : Prop := pside2 m lo shi [(P, 80); (E, 24)] [(P, 80); (E, 24)].

Lemma fh_side_intro : forall m P E lo shi,
  ACONST m -> stack0 m lo shi -> AXStatics2 m -> accessible m P 80 -> accessible m E 24 -> shvis m P (P + 80) -> shvis m E (E + 24) ->
  aapp P 80 -> aapp E 24 -> fh_side m P E lo shi.
Proof.
  intros m P E lo shi AC SK XS AP AE SVP SV APP APE. apply pside2_intro; [exact AC| exact SK| exact XS| |].
  - apply Forall_cons; [exact AP| apply Forall_cons; [exact AE| apply Forall_nil]].
  - apply Forall_cons; [| apply Forall_cons; [| apply Forall_nil]]; cbn [fst snd]; apply shv_entry; first [assumption | lia].
Qed.

(* [comment removed for export] *)
Definition fh_ctx (m m1 : mem) (sp s0v s1v s2v s3v s4v s5v s6v rav : word) (P E lo shi : Z) (c : pcore) (pad7 pad2 ej j8 j24 : list byte) (g : bool) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -96) [CB 8 j8]
  /\ rw_cells bsegs m1 (bv_unsigned sp + -88) [CB 24 j24]
  /\ rw_cells bsegs m1 (bv_unsigned sp + -64) [C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells bsegs m1 P (ParserCoreCells c pad7 pad2)
  /\ rw_cells bsegs m1 E [CB 24 ej]
  /\ stk bsegs m1 lo (bv_unsigned sp + -96)
  /\ munch (body_W lo sp P E) m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ munch [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24)]%Z m m1
  /\ AHttpCat m g /\ fh_side m P E lo shi.

Definition fh_post_r (R : ecv * pcore) (G : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo shi : Z) (pad7 pad2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' P (ParserCoreCells (snd R) pad7 pad2)
    /\ rw_cells bsegs m' E (ErrCodeCells (fst R))
    /\ AHttpCat m' G /\ AXStatics2 m'
    /\ ACONST m' /\ stack0 m' lo shi.

