Definition fh_exit_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5v s6v s1x s2x s3x s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo shi : Z) (c : pcore) (pad7 pad2 ej j8 j24 : list byte) (g : bool),
  fh_ctx m m1 sp s0v s1v s2v s3v s4v s5v s6v ra P E lo shi c pad7 pad2 ej j8 j24 g ->
  st_pure FH_STACK sp P E lo shi ->
  evt bsegs (fh_post_r (EC_http_loc e loc, c) true ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 F fc P E lo shi pad7 pad2 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 (wz E) s1x a0x a1 a2 a3 a4 a5 a6 a7
              s2x s3x (wz 2147450880) s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).

Local Ltac fh_exit_script e loc :=
  unfold fh_exit_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3v s4v s5v s6v s1x s2x s3x s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P E lo shi c pad7 pad2 ej j8 j24 g;
  intros CTX PURE;
  destruct CTX as (FR0 & TMP & FRhi & PC & EC & ST & MU & WM & MI & MUq & HC & SIDE);
  pose proof (body_pwin _ _ _ _ _ _ PURE) as FW;
  destruct PURE as (LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI);
  pose proof (ex_bnd_intro _ _ _ _ _ LO CEIL SHI APE) as BND;
  pose proof BND as BNDv; unfold ex_bnd in BNDv; destruct BNDv as (_ & _ & _ & SPR & EB1 & EB2 & EB3 & EB4 & AF1);
  pose proof (aapp_bounds _ 80 APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof (body_cat_now _ _ _ _ _ _ _ HC MUq WM CEIL APP APE) as HC1;
  clear MUq HC;
  assert (D8 : (bv_unsigned sp + -88) mod 8 = 0) by (clear - SPAL; Z.div_mod_to_equations; lia);
  clear PAL SPAL PB5 PB3 APP; hydeL DPE; hydeL EAL; hydeL D8;
  unfold body_W, FH_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold wz in *;
  assign_loc_block MEMCPY ASSIGNA SIDE MU WM FW HC1 TMP EC ST MI APE EAL D8 BND (bv_unsigned sp + -88) E e loc lo shi sp g j24 ej m;
  (* [comment removed for export] *)
  st1;
  step; step; step; step; step; step; step; step;
  lazymatch goal with
  | TMPa : rw_cells _ _ (bv_unsigned sp + -88) [C8 _; C8 _], TMPb : rw_cells _ _ (bv_unsigned sp + -72) [C8 _],
    ST3 : stk _ _ lo (bv_unsigned sp + -96) |- _ =>
      join_frameA TMPa TMPb (bv_unsigned sp + -88); join_frameA TMPa FRhi (bv_unsigned sp + -88);
      join_frameA FR0 TMPa (bv_unsigned sp + -96);
      step; release_frame FR0 ST3 (bv_unsigned sp)
  end;
  step;
  assign_loc_close SIDE FW BND E e loc m;
  unfold fh_post_r; cbn [fst snd];
  finish.
