Lemma fh_post_ok : forall R G ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo shi c pad7 pad2 g m ms',
  fh_res c = R -> (negb (ec_cat (fst R) =? 0) || g)%bool = G ->
  fh_post_r R G ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo shi pad7 pad2 m ms' ->
  fh_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo shi c pad7 pad2 g m ms'.
Proof.
  intros until ms'. intros RES ASG PO. unfold fh_post, fh_assigns. rewrite RES, ASG. exact PO.
Qed.

(* [comment removed for export] *)
Local Ltac fh_prepare FR :=
  lazymatch type of FR with rw_cells _ ?mx (?b + -96) [CB 32 ?jj; C8 ?x1; C8 ?x2; C8 ?x3; C8 ?x4; C8 ?x5; C8 ?x6; C8 ?x7; C8 ?x8] =>
    let FRlo := fresh "FRlo" in let FRhi := fresh "FRhi" in let FR0 := fresh "FR0" in let TMP := fresh "TMP" in
    split_frameA FR [CB 32 jj] [C8 x1; C8 x2; C8 x3; C8 x4; C8 x5; C8 x6; C8 x7; C8 x8] FRlo FRhi;
    destruct (rw_cells_CB_split bsegs _ _ 32 8 jj FRlo ltac:(clear; lia)) as [FR0 TMP]; clear FRlo;
    cbn [Nat.sub] in TMP; change (Z.of_nat 8) with 8 in TMP;
    replace (b + -96 + 8) with (b + -88) in TMP by (clear; lia)
  end.

(* [comment removed for export] *)
Local Ltac fh_R R c PAIR :=
  assert (R : fh_res c = PAIR);
  [ unfold fh_res; cbv zeta;
    repeat match goal with H : (_ && _)%bool = _ |- _ => rewrite H end;
    repeat match goal with H : Z.testbit _ _ = _ |- _ => rewrite H end;
    repeat match goal with
    | |- context [?a =? ?b] => first [ replace (a =? b) with true by (symmetry; apply Z.eqb_eq; lia)
                                     | replace (a =? b) with false by (symmetry; apply Z.eqb_neq; lia) ]
    | |- context [?a <? ?b] => first [ replace (a <? b) with true by (symmetry; apply Z.ltb_lt; lia)
                                     | replace (a <? b) with false by (symmetry; apply Z.ltb_ge; lia) ]
    end;
    cbn [andb negb]; reflexivity
  | ].

(* [comment removed for export] *)
Local Ltac fh_exit R L FR PURE SIDE :=
  fh_prepare FR;
  eapply evt_mono; [| intros ?ms' ?PO; eapply (fh_post_ok _ true); [exact R | reflexivity | fast_eassumption]];
  eapply L; [| exact PURE];
  unfold fh_ctx, body_W, AG_HTTP_CAT, ParserCoreCells, wz;
  cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f];
  repeat (split; [fast_eassumption|]); exact SIDE.

(* [comment removed for export] *)
Local Ltac fh_tojoin R cj stj FR PURE SIDE :=
  fh_prepare FR;
  eapply evt_mono; [| intros ?ms' ?PO; eapply (fh_post_ok _ _); [exact R | reflexivity | fast_eassumption]];
  eapply (fh_join) with (c1 := cj) (st' := stj); [| exact PURE | clear; lia];
  unfold fh_ctx, body_W, AG_HTTP_CAT, ParserCoreCells, wz;
  cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f pc_set_state_f];
  repeat (split; [fast_eassumption|]); exact SIDE.

(* [comment removed for export] *)
Local Ltac fh_len_tail c P FR PURE SIDE MU WM FW PAL :=
  let KL := fresh "KL" in let R := fresh "R" in
  ps_chk8 SIDE MU WM FW P 80 (P + 24) PAL ltac:(zstep; zstep; step);
  step; step; if_cases KL; zify_cond KL; rewrite ?unsigned_lit in KL by lia;
  [ fh_R R c (EC_clear, pc_set_state c 11);
    fh_tojoin R c 11 FR PURE SIDE
  | ps_chkin SIDE MU WM FW P 80 (P + 76) PAL ltac:(idtac; step);
    step; change (sx32 (Z_to_bv 64 (pc_f c))) with (sx32 (wz (pc_f c))); rewrite sx32_wz by lia; unfold wz;
    zstep; st1; step; step;
    fh_R R c (EC_clear, pc_set_state_f c 3 (Z.lor (pc_f c) 8));
    fh_tojoin R (pc_set_state_f c (pc_state c) (Z.lor (pc_f c) 8)) 3 FR PURE SIDE ].
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma fh_spec : fh_stmt.
